function cariBiner(arr, target) {
  let kiri = 0, kanan = arr.length - 1;
  while (kiri <= kanan) {
    const tengah = Math.floor((kiri + kanan) / 2);
    if (arr[tengah] === target) return tengah;
    if (arr[tengah] < target) kiri = tengah + 1;
    else kanan = tengah - 1;
  }
  return -1;
}

