def cari_biner(arr, target):
    kiri, kanan = 0, len(arr) - 1
    while kiri <= kanan:
        tengah = (kiri + kanan) // 2
        if arr[tengah] == target:
            return tengah
        if arr[tengah] < target:
            kiri = tengah + 1
        else:
            kanan = tengah - 1
    return -1

