func cariBiner(arr []int, target int) int {
	kiri, kanan := 0, len(arr)-1
	for kiri <= kanan {
		tengah := kiri + (kanan-kiri)/2
		switch {
		case arr[tengah] == target:
			return tengah
		case arr[tengah] < target:
			kiri = tengah + 1
		default:
			kanan = tengah - 1
		}
	}
	return -1
}
